INSERT INTO legal_pages (slug, title, body_tiptap) VALUES
('privacy', 'Privacy Policy', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Introduction"}]},{"type":"paragraph","content":[{"type":"text","text":"This Privacy Policy explains how we collect, use, store, and protect your personal information when you access our platform, purchase courses, or interact with our services. By using this platform you agree to the practices described here. This policy is effective as of the date shown at the bottom of this page."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Information We Collect"}]},{"type":"paragraph","content":[{"type":"text","text":"We collect information you provide directly: your name, email address, billing address, and payment details when you register or purchase. We also collect information automatically: IP address, browser type, device identifiers, pages visited, time spent, and course progress. Payment card details are processed and stored solely by our payment processor and are never stored on our servers."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. How We Use Your Information"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deliver and personalise your learning experience."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Process payments and send transaction receipts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send account-related emails (receipts, password resets, policy updates)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send promotional communications only with your prior consent, which you may withdraw at any time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect and prevent fraud, abuse, and security incidents."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comply with applicable legal obligations."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Sharing Your Information"}]},{"type":"paragraph","content":[{"type":"text","text":"We do not sell your personal data. We share it only with: (a) payment processors to complete transactions; (b) cloud hosting and infrastructure providers operating under data-processing agreements; (c) analytics providers on an aggregated or pseudonymised basis; and (d) law-enforcement or regulatory authorities when required by law. All third-party processors are contractually bound to protect your data."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Cookies and Tracking"}]},{"type":"paragraph","content":[{"type":"text","text":"We use strictly necessary cookies to keep you logged in and remember your preferences. With your consent we also set analytics cookies to understand how learners use the platform and improve it. You can manage or withdraw cookie consent through your browser settings at any time; doing so may affect some platform functionality."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Data Retention"}]},{"type":"paragraph","content":[{"type":"text","text":"We retain your account information for as long as your account is active. After deletion we may retain transaction records for up to seven years to meet tax and accounting obligations. Analytics data is retained in aggregated form and cannot be linked back to you once anonymised."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Your Rights"}]},{"type":"paragraph","content":[{"type":"text","text":"You have the right to access, correct, or request deletion of your personal data. Indian users may additionally exercise rights under the Digital Personal Data Protection Act, 2023 (DPDPA). EU/UK users may exercise rights under the GDPR. To make a request, contact us using the details on the Contact page. We will respond within 30 days."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Security"}]},{"type":"paragraph","content":[{"type":"text","text":"We use industry-standard measures including TLS encryption in transit, encrypted storage, and strict access controls to protect your data. No system is completely secure; in the event of a breach that affects your rights we will notify you as required by applicable law."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Children''s Privacy"}]},{"type":"paragraph","content":[{"type":"text","text":"Our platform is intended for users aged 18 and above. We do not knowingly collect personal data from minors. If you believe a minor has provided data to us, please contact us and we will delete it promptly."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. Changes to This Policy"}]},{"type":"paragraph","content":[{"type":"text","text":"We may update this policy from time to time. Material changes will be notified via email or a prominent notice on the platform at least 14 days before taking effect. Continued use of the platform after the effective date constitutes acceptance of the updated policy."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"11. Contact"}]},{"type":"paragraph","content":[{"type":"text","text":"For privacy-related queries or data requests, contact us via the Contact page. We aim to respond within 30 days."}]}]}'),
('terms', 'Terms of Service', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Acceptance of Terms"}]},{"type":"paragraph","content":[{"type":"text","text":"By accessing or using this platform you agree to be bound by these Terms of Service and all applicable laws. If you do not agree, do not use the platform. These terms apply to all visitors, registered users, and paying customers."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Account Registration"}]},{"type":"paragraph","content":[{"type":"text","text":"You must provide accurate and complete information when creating an account. You are responsible for maintaining the confidentiality of your login credentials and for all activities that occur under your account. Notify us immediately of any unauthorised use. We reserve the right to suspend or terminate accounts that violate these terms."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Course Access and Licence"}]},{"type":"paragraph","content":[{"type":"text","text":"Upon purchase you receive a limited, non-exclusive, non-transferable licence to access and view the purchased course content for personal, non-commercial use. Access is tied to your account and may not be shared, resold, sublicensed, or otherwise transferred. We may update, modify, or discontinue course content at our discretion; material changes affecting purchased courses will be communicated in advance where reasonably practicable."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Intellectual Property"}]},{"type":"paragraph","content":[{"type":"text","text":"All content on this platform — including course videos, text, images, code, and branding — is owned by or licensed to us and is protected by copyright, trademark, and other intellectual property laws. You may not reproduce, distribute, publicly display, or create derivative works from any content without our prior written consent."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. User Conduct"}]},{"type":"paragraph","content":[{"type":"text","text":"You agree not to: share account credentials or purchased content with others; use automated tools to scrape or download content; upload or transmit harmful, unlawful, or infringing material; attempt to reverse-engineer or disrupt the platform; or use the platform for any purpose that violates applicable law."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Payments and Pricing"}]},{"type":"paragraph","content":[{"type":"text","text":"All prices are displayed at checkout and are inclusive of applicable taxes unless stated otherwise. We accept the payment methods listed at checkout. In the event of a pricing error we reserve the right to cancel the order and issue a full refund. Chargebacks initiated without first contacting us may result in account suspension."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Refunds and Cancellations"}]},{"type":"paragraph","content":[{"type":"text","text":"Our Cancellation & Refund Policy governs all refund requests and is incorporated into these terms by reference. Please review it before purchasing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Disclaimers"}]},{"type":"paragraph","content":[{"type":"text","text":"The platform and its content are provided on an ''as is'' and ''as available'' basis without warranties of any kind, express or implied, including merchantability, fitness for a particular purpose, or non-infringement. We do not warrant that the platform will be uninterrupted, error-free, or free of viruses or other harmful components."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Limitation of Liability"}]},{"type":"paragraph","content":[{"type":"text","text":"To the maximum extent permitted by applicable law, our total liability to you for any claim arising out of or relating to these terms or the platform shall not exceed the amount you paid us in the 12 months preceding the claim. We shall not be liable for any indirect, incidental, special, consequential, or punitive damages."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"10. Indemnification"}]},{"type":"paragraph","content":[{"type":"text","text":"You agree to indemnify and hold us harmless from any claims, losses, damages, and expenses (including reasonable legal fees) arising from your use of the platform, your violation of these terms, or your infringement of any third-party rights."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"11. Termination"}]},{"type":"paragraph","content":[{"type":"text","text":"We may suspend or terminate your access at any time for breach of these terms, fraudulent activity, or as required by law. Upon termination your licence to access content ends. Provisions that by their nature should survive termination (including intellectual property, disclaimers, limitation of liability, and governing law) shall do so."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"12. Governing Law and Dispute Resolution"}]},{"type":"paragraph","content":[{"type":"text","text":"These terms are governed by the laws of India. Any disputes shall be subject to the exclusive jurisdiction of the courts at the location of our registered office. For consumer disputes, applicable statutory rights under Indian consumer law remain unaffected."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"13. Changes to These Terms"}]},{"type":"paragraph","content":[{"type":"text","text":"We may update these terms from time to time. Material changes will be notified via email or platform notice at least 14 days in advance. Continued use after the effective date constitutes acceptance of the updated terms."}]}]}'),
('refund', 'Cancellation & Refund Policy', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Overview"}]},{"type":"paragraph","content":[{"type":"text","text":"We want you to be satisfied with your purchase. This policy explains when and how you can request a cancellation or refund. Please read it carefully before purchasing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Refund Window"}]},{"type":"paragraph","content":[{"type":"text","text":"You may request a full refund within 7 days of the original purchase date, provided you have accessed no more than 20% of the course content. After 7 days, or after accessing more than 20% of the content, refunds are not available except where required by applicable law."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Eligible Purchases"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Individual course purchases within the 7-day window and below the 20% consumption threshold."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Subscription plans cancelled within 7 days of initial sign-up and not yet used to access gated content."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Non-Refundable Items"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Courses purchased at a promotional or sale price of more than 50% off."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bundle purchases where any included course has been more than 20% completed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Renewal charges for subscriptions — we send a reminder email before each renewal and it is your responsibility to cancel in advance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Courses for which a certificate of completion has already been issued."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. How to Request a Refund"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact us via the Contact page within the refund window. Include your order number, the email address used for the purchase, and a brief reason for the request. We may ask for additional information to verify the request."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Processing Timeline"}]},{"type":"paragraph","content":[{"type":"text","text":"We review all refund requests within 5 business days. Approved refunds are returned to the original payment method. Depending on your bank or payment provider, the credit may take 5–10 business days to appear on your statement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Subscription Cancellations"}]},{"type":"paragraph","content":[{"type":"text","text":"You may cancel a subscription at any time from your account settings. Cancellation stops future billing but does not trigger an automatic refund for the current billing period. Refunds for the current period are subject to the 7-day window described above."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Your Statutory Rights"}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing in this policy limits or excludes any rights you have under applicable consumer protection law, including the Consumer Protection Act, 2019 (India) or equivalent legislation in your jurisdiction. If you believe you have a statutory right to a refund beyond this policy, please contact us."}]}]}'),
('contact', 'Contact Us', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We are happy to help. Reach out using the details above. Our support team responds within 1 business day."}]}]}')
